import json, os, re, subprocess, tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TESTS='\n(async()=>{\n const assert=(value,message)=>{if(!value)throw Error(message)};\n for(let i=0;i<20 && document.querySelector(\'#country-code\').options.length<240;i++)await new Promise(resolve=>setTimeout(resolve,10));\n const form=document.querySelector(\'#auth-form\'),phone=form.elements.phone;\n document.querySelector(\'#switch-auth\').click();\n const select=form.elements.country_code; for(const [region,length] of [[\'AF\',9],[\'SG\',8],[\'BR\',11],[\'DE\',12]]){select.selectedIndex=[...select.options].findIndex(o=>o.dataset.region===region);select.dispatchEvent(new Event(\'change\'));phone.value=\'1\'.repeat(length);phone.dispatchEvent(new Event(\'input\'));assert(phone.checkValidity(),\'Country length accepted: \'+region);} select.value=\'+93\';select.dispatchEvent(new Event(\'change\'));phone.value=\'1\'.repeat(11);phone.dispatchEvent(new Event(\'input\'));assert(!phone.checkValidity(),\'Afghanistan rejects 11 national digits\');select.value=\'+91\';select.dispatchEvent(new Event(\'change\'));phone.value=\'\';\n const letters=new InputEvent(\'beforeinput\',{inputType:\'insertText\',data:\'a\',cancelable:true});phone.dispatchEvent(letters);assert(letters.defaultPrevented,\'Letters blocked before insertion\');\n phone.value=\'12abc34\';phone.dispatchEvent(new Event(\'input\'));assert(phone.value===\'1234\',\'Input fallback filters letters\');\n phone.value=\'\';const transfer=new DataTransfer();transfer.setData(\'text\',\'987ab654 3210\');phone.dispatchEvent(new ClipboardEvent(\'paste\',{clipboardData:transfer,cancelable:true}));assert(phone.value===\'9876543210\',\'Paste filters characters: \'+phone.value+\' max=\'+phone.maxLength+\' code=\'+select.value+\' option=\'+select.options[select.selectedIndex].outerHTML);assert(phone.checkValidity(),\'India 10 digits accepted\');\n phone.value=\'987654321\';phone.dispatchEvent(new Event(\'input\'));assert(!phone.checkValidity(),\'India 9 digits rejected\');\n phone.value=\'9876543210\';phone.dispatchEvent(new Event(\'input\'));\n const set=(name,value)=>{form.elements[name].value=value;form.elements[name].dispatchEvent(new Event(\'input\'));};\n set(\'first_name\',\'123\');assert(!form.elements.first_name.checkValidity(),\'Numeric name rejected\');\n set(\'first_name\',\'Anne-Marie\');assert(form.elements.first_name.checkValidity(),\'Hyphenated name accepted\');\n set(\'last_name\',"O\'Connor");assert(form.elements.last_name.checkValidity(),\'Apostrophe accepted\');\n set(\'company\',\'   \');assert(!form.elements.company.checkValidity(),\'Whitespace company rejected\');set(\'company\',\'A & B Ltd.\');\n set(\'email\',\'a..b@example.com\');assert(!form.elements.email.checkValidity(),\'Invalid email rejected\');set(\'email\',\'person@example.com\');\n set(\'password\',\'        \');assert(!form.elements.password.checkValidity(),\'Blank password rejected\');set(\'password\',\'short\');assert(!form.elements.password.checkValidity(),\'Short password rejected\');\n await form.onsubmit({preventDefault(){}});assert(window.posts===0,\'Invalid form sends no API request\');\n set(\'password\',\'valid-password\');assert(form.checkValidity(),\'Valid registration passes\');\n document.querySelector(\'#toggle-password\').click();assert(form.elements.password.type===\'text\',\'Password toggle works\');\n document.querySelector(\'#switch-auth\').click();assert(form.elements.password.type===\'password\',\'Switch hides password\');assert(phone.disabled && form.elements.first_name.disabled,\'Signup fields disabled in login\');\n set(\'password\',\'x\');assert(form.elements.password.checkValidity(),\'Login allows existing passwords\');\n document.querySelector(\'#switch-auth\').click();await form.onsubmit({preventDefault(){}});assert(window.posts===0,\'Signup revalidates password after mode switch\');\n document.body.innerHTML=\'<pre id="smoke-result">PASS: account input, paste, validation, and form-switch checks</pre>\';\n})().catch(error=>{document.body.innerHTML=\'<pre id="smoke-result"></pre>\';document.querySelector(\'pre\').textContent=\'FAIL: \'+error.stack;});\n'
def main():
    chrome = Path(os.environ.get('PROGRAMFILES', 'C:/Program Files')) / 'Google/Chrome/Application/chrome.exe'
    if not chrome.exists():
        raise SystemExit('Chrome not installed')
    html = (ROOT / 'frontend/index.html').read_text(encoding='utf-8')
    js = (ROOT / 'frontend/auth.js').read_text(encoding='utf-8')
    html = re.sub(r'<link rel="stylesheet"[^>]*>', lambda _: '<style>'+(ROOT/'frontend/styles.css').read_text(encoding='utf-8')+'</style>',html)
    countries = (ROOT / 'frontend/country-codes.json').read_text(encoding='utf-8')
    mock = "window.initialize=()=>{};window.showNotice=()=>{};window.fetch=async(path,options)=>{if(options?.method==='POST')window.posts++;return {ok:path.endsWith('/countries'),json:async()=>path.endsWith('/countries')?"+countries+":{detail:'Please log in to continue.'}}};window.posts=0;"
    html = re.sub(r'<script src="[^\"]+" defer></script>', '', html)
    html = html.replace('</body>', '<script>'+mock+'\n'+js+'\n'+TESTS+'</script></body>')
    with tempfile.TemporaryDirectory(prefix='dq-smoke-') as tmp:
        page = Path(tmp)/'smoke.html'; page.write_text(html, encoding='utf-8')
        result = subprocess.run([str(chrome),'--headless','--disable-gpu','--no-first-run','--no-default-browser-check', '--user-data-dir='+str(Path(tmp)/'profile'),'--virtual-time-budget=3000','--dump-dom',page.as_uri()],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=45)
        match = re.search(r'<pre id="smoke-result">(.*?)</pre>',result.stdout,re.S)
        if not match: raise SystemExit('Browser did not complete checks: '+result.stderr[-1000:])
        print(match.group(1))
        if not match.group(1).startswith('PASS'): raise SystemExit(1)

if __name__ == '__main__':
    main()
